package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.database.*;import android.widget.*;import java.util.*;
/** Collections and labels follow the book hash, including copies shared with courses. */
final class BookCategories {
 static final class Filter{final String where;final String[] args;Filter(String where,String[] args){this.where=where;this.args=args;}}
 static Filter filter(Context c,BookQuery base,String type,String value){if(type.isEmpty()||value.isEmpty())return new Filter(base.where,base.args);List<String> args=new ArrayList<>();if(base.args!=null)args.addAll(Arrays.asList(base.args));String clause;if(type.equals("author")){clause="author=?";args.add(value);}else try(PlusStore db=new PlusStore(c)){clause=PlusStore.inHashes(db.hashes(type,value));}return new Filter(base.where+" AND ("+clause+")",args.isEmpty()?null:args.toArray(new String[0]));}
 static void edit(Activity a,StudyStore.Row book,Runnable changed){a.startActivity(new Intent(a,CollectionEditorActivity.class).putExtra("hash",book.s("hash")));}
 static void saveChanges(Context c,String hash,String topic,String series,String name,Map<Long,Boolean> changes){hash=PlusStore.hash(hash);try(PlusStore db=new PlusStore(c)){android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{sql.execSQL("INSERT OR IGNORE INTO book_meta(hash) VALUES(?)",new Object[]{hash});sql.update("book_meta",StudyStore.values("topic",topic,"series",series),"hash=?",new String[]{hash});for(Map.Entry<Long,Boolean> e:changes.entrySet()){if(e.getValue()){try(Cursor found=sql.query("collections",new String[]{"id"},"id=?",new String[]{""+e.getKey()},null,null,null)){if(found.moveToFirst())db.save("book_collections",StudyStore.values("hash",hash,"collection",e.getKey()));}}else sql.delete("book_collections","hash=? AND collection=?",new String[]{hash,""+e.getKey()});}if(!name.isEmpty())db.save("book_collections",StudyStore.values("hash",hash,"collection",collection(db,name)));sql.setTransactionSuccessful();}finally{sql.endTransaction();}}}
 static long collection(PlusStore db,String name){name=StudySchedule.valid(name,100,"Colecção");List<StudyStore.Row> found=db.rows("collections","name=?",new String[]{name},null,1);return found.isEmpty()?db.save("collections",StudyStore.values("name",name)):found.get(0).id();}
 static void choose(BookLibrary library){Activity a=library.a;UiPanel panel=new UiPanel(a,"Colecções e grupos",null,"book");panel.action("book","Todos os livros",null,false,()->set(library,"","",""));panel.action("check","Estado de leitura",null,false,library::readingGroups);String[] labels={"Colecção","Assunto","Série","Autor"},types={"collection","topic","series","author"};for(int i=0;i<types.length;i++){final String type=types[i],label=labels[i];panel.action("folder",label,null,false,()->list(library,type,label));}panel.action("edit","Gerir colecções",null,false,()->manage(a,library::reload));panel.show();}
 static void list(BookLibrary library,String type,String label){Activity a=library.a;PagedPicker.show(a,label,(query,offset,limit)->{List<PagedPicker.Entry> rows=new ArrayList<>();long total;String pattern=StudySchedule.like(query);if(type.equals("author")){try(StudyStore db=new StudyStore(a)){String from=" FROM (SELECT DISTINCT author AS value FROM materials WHERE author<>'' AND author LIKE ? ESCAPE '\\')";try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*)"+from,new String[]{pattern})){count.moveToFirst();total=count.getLong(0);}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT value"+from+" ORDER BY value COLLATE NOCASE LIMIT ? OFFSET ?",new String[]{pattern,""+limit,""+offset})){while(c.moveToNext())rows.add(new PagedPicker.Entry(c.getString(0),c.getString(0),""));}}}else try(PlusStore db=new PlusStore(a)){String from=type.equals("collection")?" FROM collections WHERE name LIKE ? ESCAPE '\\'":" FROM (SELECT DISTINCT "+type+" AS name FROM book_meta WHERE "+type+"<>'' AND "+type+" LIKE ? ESCAPE '\\')";try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*)"+from,new String[]{pattern})){count.moveToFirst();total=count.getLong(0);}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT "+(type.equals("collection")?"id,name":"name,name")+from+" ORDER BY name COLLATE NOCASE LIMIT ? OFFSET ?",new String[]{pattern,""+limit,""+offset})){while(c.moveToNext())rows.add(new PagedPicker.Entry(c.getString(0),c.getString(1),""));}}return new PagedPicker.Page(rows,total);},e->set(library,type,e.id,e.label));}
 static void set(BookLibrary b,String type,String value,String title){b.prefs.edit().putString("group_type",type).putString("group_value",value).putString("group_title",title).apply();b.page=0;b.reload();}
 static void manage(Activity a,Runnable changed){UiPanel panel=new UiPanel(a,"Colecções",null,"folder");panel.action("add","Nova colecção",null,false,()->rename(a,null,changed));panel.action("edit","Procurar e gerir colecções",null,false,()->PagedPicker.show(a,"Colecções",(query,offset,limit)->{List<PagedPicker.Entry> out=new ArrayList<>();long total;try(PlusStore db=new PlusStore(a)){String[] args={StudySchedule.like(query)};try(Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM collections WHERE name LIKE ? ESCAPE '\\'",args)){c.moveToFirst();total=c.getLong(0);}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM collections WHERE name LIKE ? ESCAPE '\\' ORDER BY name COLLATE NOCASE LIMIT ? OFFSET ?",new String[]{args[0],""+limit,""+offset})){while(c.moveToNext())out.add(new PagedPicker.Entry(c.getString(0),c.getString(1),""));}}return new PagedPicker.Page(out,total);},e->{StudyStore.Row r=new StudyStore.Row();r.put("id",e.id);r.put("name",e.label);rename(a,r,changed);}));panel.show();}
 static void rename(Activity a,StudyStore.Row row,Runnable changed){EditText input=PlusUi.input(a,"Nome da colecção",row==null?"":row.s("name"),100);UiDialog dialog=new UiDialog.Builder(a).setTitle(row==null?"Nova colecção":"Colecção").setView(input).setPositiveButton("Guardar",null).setNeutralButton(row==null?null:"Eliminar",(d,w)->{if(row!=null)new UiDialog.Builder(a).setTitle("Eliminar colecção?").setMessage("Os livros continuam na biblioteca.").setPositiveButton("Eliminar",(x,n)->PlusUi.run(a,()->{try(PlusStore db=new PlusStore(a)){db.getWritableDatabase().beginTransaction();try{db.getWritableDatabase().delete("book_collections","collection=?",new String[]{""+row.id()});db.getWritableDatabase().delete("collections","id=?",new String[]{""+row.id()});db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}}PlusUi.post(a,changed);})).setNegativeButton("Cancelar",null).show();}).setNegativeButton("Fechar",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{String name=input.getText().toString().trim();if(name.isEmpty()){PlusUi.toast(a,"Preencha o nome.");return;}PlusUi.run(a,()->{try(PlusStore db=new PlusStore(a)){if(row==null)collection(db,name);else db.getWritableDatabase().update("collections",StudyStore.values("name",name),"id=?",new String[]{""+row.id()});}PlusUi.post(a,()->{dialog.dismiss();changed.run();manage(a,changed);});});});}
 private BookCategories(){}
}
